 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Full separator rows/columns divide the canvas into equal-sized cells.
    sep_rows = [r for r, row in enumerate(g) if row and all(v == row[0] and v != 0 for v in row)]
    sep_cols = [c for c in range(w) if all(g[r][c] != 0 and g[r][c] == g[0][c] for r in range(h))]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_spans = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_spans = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    # The leftmost compartment in each band holds that band's fill color.
    band_colors = []
    for r0, r1 in row_spans:
        vals = [g[r][c] for r in range(r0, r1) for c in range(col_spans[0][0], col_spans[0][1]) if g[r][c] != 0]
        band_colors.append(vals[0] if vals else 0)

    # Read the template's occupied positions from a non-leftmost compartment.
    pattern = None
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans[1:], start=1):
            positions = [(r - r0, c - c0) for r in range(r0, r1) for c in range(c0, c1) if g[r][c] != 0]
            if positions:
                pattern = positions
                break
        if pattern is not None:
            break
    if pattern is None:
        return g

    # Clear compartments, then stamp the template in each compartment using its band color.
    for ri, (r0, r1) in enumerate(row_spans):
        color = band_colors[ri]
        for c0, c1 in col_spans:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    g[r][c] = 0
            for dr, dc in pattern:
                if r0 + dr < r1 and c0 + dc < c1:
                    g[r0 + dr][c0 + dc] = color
    return g
